    /// <summary>
    /// extension of method to update the invoice date when multiple PO are selected to invoice
    /// </summary>
    /// <param name = "_origPurchSubTableSet"></param>
    /// <param name = "_newPurchLineSet"></param>
    /// <param name = "_vendInvoiceInfoTable"></param>
    public void purchSelectLines(Set _origPurchSubTableSet, Set _newPurchLineSet, VendInvoiceInfoTable _vendInvoiceInfoTable)
    {
        next purchSelectLines(_origPurchSubTableSet, _newPurchLineSet, _vendInvoiceInfoTable);

        this.metUpdateParmTableInvoiceDate();
    }

    /// <summary>
    /// update the invoice date of the invoice
    /// </summary>
    private void metUpdateParmTableInvoiceDate()
    {
        VendPackingSlipJour     vendPackingSlipJour;
        VendPackingSlipTrans    vendPackingSlipTrans;
        VendInvoiceInfoSubLine  vendInvoiceInfoSubLine;
        VendInvoiceInfoLine     vendInvoiceInfoLine;
        VendInvoiceInfoTable    vendInvoiceInfoTable = VendInvoiceInfoTable::findRecId(parmTable.RecId, true);
        
        if(VendParameters::find().METDefaultInvDate)
        {
            select firstonly DeliveryDate from vendPackingSlipJour
                        order by DeliveryDate asc
                    exists join vendPackingSlipTrans
                        where   vendPackingSlipTrans.VendPackingSlipJour    == vendPackingSlipJour.RecId
                    exists join VendInvoiceInfoSubLine
                        where   VendInvoiceInfoSubLine.JournalRefRecId      == vendPackingSlipTrans.RecId &&
                                VendInvoiceInfoSubLine.JournalRefTableId    == tableNum(VendPackingSlipTrans)
                    exists join vendInvoiceInfoLine
                        where   vendInvoiceInfoLine.RecId       == VendInvoiceInfoSubLine.LineRefRecId &&
                                vendInvoiceInfoLine.ParmId      == vendInvoiceInfoTable.ParmId &&
                                vendInvoiceInfoLine.TableRefId  == vendInvoiceInfoTable.TableRefId;

            if(vendPackingSlipJour && vendPackingSlipJour.DeliveryDate != vendInvoiceInfoTable.DocumentDate)
            {
                ttsbegin;
                vendInvoiceInfoTable.DocumentDate = vendPackingSlipJour.DeliveryDate;
                vendInvoiceInfoTable.update();
                ttscommit;
            }
        }
    }
